// Revisa salud del sitio y del inventario. Una oferta vence ~15 días después de cargada (precio_visto).
const r = $input.first().json;
const hoy = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Argentina/Buenos_Aires' }));
const iso = d => d.toISOString().slice(0, 10);
const hoyIso = iso(hoy);
const problemas = [];
if (r.statusCode !== 200 || !Array.isArray(r.body)) {
  problemas.push(`🔴 El sitio no responde bien (código ${r.statusCode}).`);
  return [{ json: { alerta: true, texto: problemas.join('\n') } }];
}
const ofertas = r.body;
const total = ofertas.length;
const cargadasHoy = ofertas.filter(o => o.precio_visto === hoyIso).length;
const limite = new Date(hoy); limite.setDate(limite.getDate() - 12);
const porVencer = ofertas.filter(o => o.precio_visto && o.precio_visto <= iso(limite)).length;
const tecno = ofertas.filter(o => /notebook|celular|iphone|samsung galaxy|smart tv|televisor/i.test(o.titulo || '')).length;
if (total < 1500) problemas.push(`🟠 Quedan solo ${total} ofertas en el sitio (mínimo 1.500).`);
if (cargadasHoy === 0) problemas.push('🟠 Hoy no se cargó ninguna oferta: la tarea de las 11:13 no corrió o falló. ¿Brave abierto y la extensión conectada?');
if (porVencer > 300) problemas.push(`🟡 ${porVencer} ofertas vencen en los próximos 3 días: hay que recargarlas.`);
const resumen = `Sitio: ${total} ofertas · cargadas hoy: ${cargadasHoy} · tecno: ${tecno} · por vencer: ${porVencer}`;
return [{ json: { alerta: problemas.length > 0, texto: (problemas.length ? problemas.join('\n') + '\n\n' : '✅ Todo en orden.\n') + resumen } }];
